-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/ahtUrhgan/When_the_Bow_Breaks.lua"]={["Path"]="scripts/quests/ahtUrhgan/When_the_Bow_Breaks.lua",["SHA256"]="ee184052362e67d7689a74092587c3ee429f00a74a95ec7b7d2cfdcc7a76965e",["Text"]="-----------------------------------\n-- When the Bow Breaks\n-----------------------------------\n-- Log ID: 6, Quest ID: 45\n-- Gaweesh: !pos -64 -7 38 48\n-- Giwahb Watchtower: !pos -339 -37 654 51\n-----------------------------------\nlocal ID = zones[xi.zone.WAJAOM_WOODLANDS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.WHEN_THE_BOW_BREAKS)\n\nquest.reward =\n{\n    title = xi.title.GALESERPENT_GUARDIAN,\n}\n\nquest.sections =\n{\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.ODE_TO_THE_SERPENTS) == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AL_ZAHBI] =\n        {\n            ['Gaweesh'] = quest:progressEvent(280),\n\n            onEventFinish =\n            {\n                [280] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WAJAOM_WOODLANDS] =\n        {\n            ['Giwahb_Watchtower'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.FRAYED_ARROW) then\n                        return quest:progressEvent(512)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [512] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:messageSpecial(ID.text.INCREASED_STANDING)\n                        player:addCurrency('imperial_standing', 500)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/A_Flash_in_the_Pan.lua"]={["Path"]="scripts/quests/bastok/A_Flash_in_the_Pan.lua",["SHA256"]="a42373e0e6c5c1e55c3e0e15563147a39947c93877d9edca06380436e8c803f0",["Text"]="-----------------------------------\n-- A Flash in the Pan\n-----------------------------------\n-- Log ID: 1, Quest ID: 14\n-- Aquillina : !pos -97 -5 -81 235\n-----------------------------------\nlocal bastokMarketsID = zones[xi.zone.BASTOK_MARKETS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.A_FLASH_IN_THE_PAN)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 100,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Aquillina'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npc:getLocalVar('tradeCooldown') > GetSystemTime() then\n                        return quest:event(218)\n                    end\n\n                    if npcUtil.tradeMatches(trade, { { xi.item.FLINT_STONE, 4 } }) then\n                        return quest:progressEvent(219) -- She does NOT care if you ever spoke to her.\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if npc:getLocalVar('tradeCooldown') <= GetSystemTime() then\n                        return quest:progressEvent(217)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [217] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n\n                [219] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        GetNPCByID(bastokMarketsID.npc.AQUILLINA):setLocalVar('tradeCooldown', GetSystemTime() + 900)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Aquillina'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npc:getLocalVar('tradeCooldown') > GetSystemTime() then\n                        return quest:event(218)\n                    end\n\n                    if npcUtil.tradeMatches(trade, { { xi.item.FLINT_STONE, 4 } }) then\n                        return quest:progressEvent(219) -- She does NOT care if you ever spoke to her.\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if npc:getLocalVar('tradeCooldown') <= GetSystemTime() then\n                        return quest:event(217)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [219] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        GetNPCByID(bastokMarketsID.npc.AQUILLINA):setLocalVar('tradeCooldown', GetSystemTime() + 900)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/A_Foremans_Best_Friend.lua"]={["Path"]="scripts/quests/bastok/A_Foremans_Best_Friend.lua",["SHA256"]="be8e417054a47a244b046e3b0f9e26453e2bb7d255c465d5dd55507649adcc45",["Text"]="-----------------------------------\n-- A Foreman's Best Friend\n-----------------------------------\n-- Log ID: 1, Quest ID: 9\n-- Gudav : !pos -3.286 1.407 50.591 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.A_FOREMANS_BEST_FRIEND)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Gudav'] = quest:progressEvent(110),\n\n            onEventFinish =\n            {\n                [110] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Dehlner'] = quest:event(111),\n\n            ['Gudav'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.DOG_COLLAR, 1 } }) then\n                        return quest:progressEvent(112)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [112] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        if player:hasKeyItem(xi.keyItem.MAP_OF_THE_GUSGEN_MINES) then\n                            player:addExp(2000)\n                        else\n                            npcUtil.giveKeyItem(player, xi.keyItem.MAP_OF_THE_GUSGEN_MINES)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/A_Ladys_Heart.lua"]={["Path"]="scripts/quests/bastok/A_Ladys_Heart.lua",["SHA256"]="6fdde3038793c43b3e337d382b75811f84370b20de5e275e2678a83abf13253b",["Text"]="-----------------------------------\n-- A Lady's Heart\n-----------------------------------\n-- Log ID: 1, Quest ID: 50\n-- Valah Molkot : !pos 59 8 -221 236\n-----------------------------------\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.A_LADYS_HEART)\n\nquest.reward =\n{\n    fame     = 0,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nlocal flowerItems =\n{\n    xi.item.AMARYLLIS,\n    xi.item.ASPHODEL,\n    xi.item.CARNATION,\n    xi.item.CASABLANCA,\n    xi.item.CATTLEYA,\n    xi.item.CHAMOMILE,\n    xi.item.DAHLIA,\n    xi.item.FLAX_FLOWER,\n    xi.item.LILAC,\n    xi.item.LYCOPODIUM_FLOWER,\n    xi.item.MARGUERITE,\n    xi.item.OLIVE_FLOWER,\n    xi.item.PAPAKA_GRASS,\n    xi.item.PHALAENOPSIS,\n    xi.item.RAIN_LILY,\n    xi.item.RED_ROSE,\n    xi.item.SNOW_LILY,\n    xi.item.SWEET_WILLIAM,\n    xi.item.TAHRONGI_CACTUS,\n    xi.item.WATER_LILY,\n    xi.item.WIJNRUIT,\n}\n\nlocal function isTradeInTable(trade, itemTable)\n    for _, itemId in ipairs(itemTable) do\n        if npcUtil.tradeMatches(trade, { { itemId, 1 } }) then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Valah_Molkot'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.AMARYLLIS, 1 } }) then\n                        return quest:progressEvent(160, 0, 236, 2)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(160, 0, 236, 1)\n                    else\n                        return quest:progressEvent(160, 0, 236, 0)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(160, 0, 236, 10),\n            },\n\n            onEventFinish =\n            {\n                [160] = function(player, csid, option, npc)\n                    -- Three possible event options are returned from the above triggers:\n                    -- 0    : Invalid Item was traded\n                    -- 1    : Valid Item was traded\n                    -- 10   : Cancel/Exit event option.\n                    -- 2002 : Amaryllis was traded\n\n                    -- Correct trade option (Amaryllis).\n                    if option == 2002 then\n                        if quest:complete(player) then\n                            player:tradeComplete()\n                            local mhflag = player:getMoghouseFlag()\n                            player:setMoghouseFlag(mhflag + 0x0002)\n                            player:messageSpecial(portBastokID.text.MOGHOUSE_EXIT)\n                        end\n\n                    else\n                        if option == 1 then\n                            player:tradeComplete()\n                        end\n\n                        if player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_AVAILABLE then\n                            quest:begin(player)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Valah_Molkot'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- NOTE: After completing this quest, trade is not consumed.\n\n                    if npcUtil.tradeMatches(trade, { { xi.item.AMARYLLIS, 1 } }) then\n                        return quest:progressEvent(160, 0, 236, 4)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(160, 0, 236, 5)\n                    else\n                        return quest:progressEvent(160, 0, 236, 0)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(160, 0, 236, 10),\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/A_Question_of_Faith.lua"]={["Path"]="scripts/quests/bastok/A_Question_of_Faith.lua",["SHA256"]="56098a0966f802e1d32ccf6af44643175eaf99fac4a12758c8f012dc7efaa29b",["Text"]="-----------------------------------\n-- A Question of Faith\n-----------------------------------\n-- Area: Metalworks\n-- NPC: Ayame !pos 132 -18 33 237\n-- NPC: Virnage !pos 0.7 -0.0 49 234\n-- NPC: Rakorok !pos 158 13 -42 11\n-----------------------------------\nlocal ID  = zones[xi.zone.OLDTON_MOVALPOLOS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.A_QUESTION_OF_FAITH)\n\nquest.reward =\n{\n    fame = 40,\n    fameArea = xi.fameArea.BASTOK,\n    gil = 3000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getFameLevel(xi.fameArea.BASTOK) >= 4 and\n            player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.OUT_OF_THE_DEPTHS)\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] = quest:progressEvent(875),\n\n            onEventFinish =\n            {\n                [875] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Virnage'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.DAWN_TALISMAN) and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(239, 0, xi.keyItem.DAWN_TALISMAN)\n                    elseif player:hasKeyItem(xi.keyItem.DAWN_TALISMAN) then\n                        return quest:event(242, 0, xi.keyItem.DAWN_TALISMAN)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(241)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [239] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.DAWN_TALISMAN)\n                    end\n                end,\n\n                [241] = function(player, csid, option, npc)\n                        quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Rakorok'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.DAWN_TALISMAN) and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        if npcUtil.popFromQM(player, npc, ID.mob.BUGALLUG, { claim = true, hide = 0 }) then\n                            player:messageSpecial(ID.text.ALTANA_DIE)\n                            return quest:messageSpecial(ID.text.MONSTER_APPEARED)\n                        end\n                    elseif\n                        quest:getVar(player, 'Prog') == 1 and\n                        player:hasKeyItem(xi.keyItem.DAWN_TALISMAN)\n                    then\n                        return quest:progressEvent(6, 11, xi.keyItem.DAWN_TALISMAN)\n                    end\n                end,\n            },\n\n            ['Bugallug'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.DAWN_TALISMAN)\n                    player:messageSpecial(ID.text.WAS_TAKEN_FROM_YOU, 0, xi.keyItem.DAWN_TALISMAN)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/A_Test_of_True_Love.lua"]={["Path"]="scripts/quests/bastok/A_Test_of_True_Love.lua",["SHA256"]="abab3d5c84e6ad67e9971c57b75e57baeb80616ba7b7dbfbc0cb2c5b808e578d",["Text"]="-----------------------------------\n-- A Test of True Love\n-----------------------------------\n-- Log ID: 1, Quest ID: 62\n-- Carmelo : !pos -146.476 -7.48 -10.889 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.A_TEST_OF_TRUE_LOVE)\n\nquest.reward =\n{\n    fame     = 70,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 10000,\n}\n\nlocal pageKeyItems =\n{\n    xi.keyItem.UN_MOMENT,\n    xi.keyItem.LEPHEMERE,\n    xi.keyItem.LANCIENNE,\n}\n\nlocal function getNumPages(player)\n    local numPages = 0\n\n    for _, keyItemId in ipairs(pageKeyItems) do\n        if player:hasKeyItem(keyItemId) then\n            numPages = numPages + 1\n        end\n    end\n\n    return numPages\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.LOVE_AND_ICE) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 6 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] = quest:progressEvent(270),\n\n            onEventFinish =\n            {\n                [270] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_BAILEYS] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.UN_MOMENT) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.UN_MOMENT)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CASTLE_ZVAHL_KEEP] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.UN_MOMENT) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.UN_MOMENT)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LABYRINTH_OF_ONZOZO] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.LANCIENNE) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.LANCIENNE)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        if getNumPages(player) == 3 then\n                            return quest:progressEvent(272)\n                        else\n                            return quest:event(271)\n                        end\n                    elseif questProgress == 1 then\n                        if not quest:getMustZone(player) then\n                            return quest:progressEvent(274)\n                        else\n                            return quest:event(273)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [272] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    quest:setMustZone(player)\n                end,\n\n                [274] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.LOVERS_IN_THE_DUSK)\n\n                        -- TODO: Removing KIs at this step needs to be verified, but given the KI for Lovers in the Dusk\n                        -- references they are all arranged, this is most likely correct.\n\n                        for _, keyItemId in ipairs(pageKeyItems) do\n                            player:delKeyItem(keyItemId)\n                        end\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SEA_SERPENT_GROTTO] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not player:hasKeyItem(xi.keyItem.LEPHEMERE) then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.LEPHEMERE)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Altanas_Sorrow.lua"]={["Path"]="scripts/quests/bastok/Altanas_Sorrow.lua",["SHA256"]="0f75fea971fbbe0ac3d6cb48a2490b5141fddbbb4d4402ff65f852f971594fee",["Text"]="-----------------------------------\n-- Altana's Sorrow\n-----------------------------------\n-- Log ID: 1, Quest ID: 49\n-- Virnage : !pos 0 0 51 234\n-- qm1     : !pos -282.339 0.001 261.707 200\n-- Eperdur : !pos 129 -6 96 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.ALTANAS_SORROW)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SCROLL_OF_TELEPORT_DEM,\n    title    = xi.title.PILGRIM_TO_DEM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 10 and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 4\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Virnage'] = quest:progressEvent(141),\n\n            onEventFinish =\n            {\n                [141] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Virnage'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.BUCKET_OF_DIVINE_PAINT) then\n                        player:startEvent(143)\n                    elseif player:hasKeyItem(xi.keyItem.LETTER_FROM_VIRNAGE) then\n                        player:startEvent(144)\n                    else\n                        player:startEvent(142)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [143] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.BUCKET_OF_DIVINE_PAINT)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_VIRNAGE)\n                end,\n            },\n        },\n\n        [xi.zone.GARLAIGE_CITADEL] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.BUCKET_OF_DIVINE_PAINT) and\n                        not player:hasKeyItem(xi.keyItem.LETTER_FROM_VIRNAGE)\n                    then\n                        return quest:keyItem(xi.keyItem.BUCKET_OF_DIVINE_PAINT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Eperdur'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.LETTER_FROM_VIRNAGE) then\n                        return quest:progressEvent(679)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [679] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.LETTER_FROM_VIRNAGE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Virnage'] = quest:event(145):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Ayame_and_Kaede.lua"]={["Path"]="scripts/quests/bastok/Ayame_and_Kaede.lua",["SHA256"]="65325cfb51271af0ab42af52a5f42c600dd9f3fb559a17dd5061baba4edcc7e4",["Text"]="-----------------------------------\n-- Ayame and Kaede\n-----------------------------------\n-- Log ID: 1, Quest ID: 60\n-- Kaede    : !pos 48 -6 67 236\n-- Kagetora : !pos -96 -2 29 236\n-- Ensetsu  : !pos 33 -6 67 236\n-- qm2      : !pos -208 -9 176 173\n-- Ryoma    : !pos -23 0 -9 252\n-----------------------------------\nlocal korrolokaID  = zones[xi.zone.KORROLOKA_TUNNEL]\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.AYAME_AND_KAEDE)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    keyItem  = xi.keyItem.JOB_GESTURE_NINJA,\n    title    = xi.title.SHADOW_WALKER,\n}\n\nlocal function isNMSpawned()\n    for nmId = korrolokaID.mob.KORROLOKA_LEECH, korrolokaID.mob.KORROLOKA_LEECH + 2 do\n        if GetMobByID(nmId):isSpawned() then\n            return true\n        end\n    end\n\n    return false\nend\n\nlocal function isNMDefeated()\n    for nmId = korrolokaID.mob.KORROLOKA_LEECH, korrolokaID.mob.KORROLOKA_LEECH + 2 do\n        if GetMobByID(nmId):isDead() then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kaede'] = quest:progressEvent(240),\n\n            onEventFinish =\n            {\n                [240] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KORROLOKA_TUNNEL] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not isNMSpawned() and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        if quest:getLocalVar(player, 'nmDefeated') == 1 then\n                            quest:setVar(player, 'Prog', 3)\n\n                            if quest:getLocalVar(player, 'isActor') == 1 then\n                                quest:setLocalVar(player, 'isActor', 0)\n                                npc:hideNPC(xi.settings.main.FORCE_SPAWN_QM_RESET_TIME)\n                            end\n\n                            return quest:keyItem(xi.keyItem.STRANGELY_SHAPED_CORAL)\n                        else\n                            quest:setLocalVar(player, 'isActor', 1)\n\n                            for nmId = korrolokaID.mob.KORROLOKA_LEECH, korrolokaID.mob.KORROLOKA_LEECH + 2 do\n                                SpawnMob(nmId):updateClaim(player)\n                            end\n\n                            return quest:messageText(korrolokaID.text.HAIR_STANDS_ON_END)\n                        end\n                    end\n                end,\n            },\n\n            ['Korroloka_Leech'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        isNMDefeated() and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        quest:setLocalVar(player, 'nmDefeated', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['Ryoma'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(95)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [95] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SEALED_DAGGER)\n                    player:delKeyItem(xi.keyItem.STRANGELY_SHAPED_CORAL)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ensetsu'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress >= 1 and\n                        questProgress <= 2\n                    then\n                        return quest:progressEvent(242)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(245)\n                    elseif questProgress == 4 then\n                        return quest:event(243)\n                    elseif questProgress == 5 then\n                        return quest:progressEvent(246, xi.keyItem.SEALED_DAGGER)\n                    end\n                end,\n            },\n\n            ['Kagetora'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(241)\n                    elseif questProgress > 2 then\n                        return quest:event(244)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [241] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [242] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [245] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [246] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SEALED_DAGGER)\n                        player:unlockJob(xi.job.NIN)\n                        player:messageSpecial(portBastokID.text.UNLOCK_NINJA)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kaede'] = quest:event(248):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Beadeaux_Smog.lua"]={["Path"]="scripts/quests/bastok/Beadeaux_Smog.lua",["SHA256"]="224fd0b45357a6f06190e206b9677952f4e5972cb13fdbc11303e949f04fae4c",["Text"]="-----------------------------------\n-- Beadeaux Smog\n-----------------------------------\n-- Log ID: 1, Quest ID: 33\n-- High Bear    : !pos 25.231 -14.999 4.552 237\n-- qm1 (for KI) : !pos -58.873 1.026 -116.665 147\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BEADEAUX_SMOG)\n\nquest.reward =\n{\n    fame = 40,\n    fameArea = xi.fameArea.BASTOK,\n    title = xi.title.BEADEAUX_SURVEYOR,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.BASTOK) >= 4\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['High_Bear'] = quest:progressEvent(731),\n\n            onEventFinish =\n            {\n                [731] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and not player:hasKeyItem(xi.keyItem.CORRUPTED_DIRT)\n        end,\n\n        -- While the quest is accepted, High Bear uses his default text\n\n        [xi.zone.BEADEAUX] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:keyItem(xi.keyItem.CORRUPTED_DIRT)\n                end,\n            },\n        },\n    },\n\n    -- Section: Hand in quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasKeyItem(xi.keyItem.CORRUPTED_DIRT)\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['High_Bear'] = quest:progressEvent(732),\n\n            onEventFinish =\n            {\n                [732] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CHAKRAM) then\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Beauty_and_the_Galka.lua"]={["Path"]="scripts/quests/bastok/Beauty_and_the_Galka.lua",["SHA256"]="0f863bb7e1d1eaefac9bb3d882b2077095aff08cd5e326a3890dbe4613c9532c",["Text"]="-----------------------------------\n-- Beauty and the Galka\n-----------------------------------\n-- Log ID: 1, Quest ID: 1\n-- Talib : !pos -101.133 4.649 28.803 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BEAUTY_AND_THE_GALKA)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.BRONZE_KNIFE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Talib'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(4) -- Denied Cornelia's request.\n                    else\n                        return quest:progressEvent(2) -- First time.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    if option == 1 then -- Decline quest\n                        quest:setVar(player, 'Prog', 1)\n                    else\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Parraggoh'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(7) -- Cornelia told the player of Parraggoh's predicament.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Talib'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(4)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasKeyItem(xi.keyItem.PALBOROUGH_MINES_LOGS) and\n                        npcUtil.tradeMatches(trade, { { xi.item.CHUNK_OF_ZINC_ORE, 1 } })\n                    then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.PALBOROUGH_MINES_LOGS)\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Parraggoh'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.PALBOROUGH_MINES_LOGS) then\n                        return quest:progressEvent(10, quest:getVar(player, 'Prog'))\n                    elseif math.randomInt(1, 100) <= 50 then\n                        return quest:event(8)\n                    else\n                        return quest:event(9)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.PALBOROUGH_MINES_LOGS)\n                    end\n                end,\n            },\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            -- New default texts.\n            ['Parraggoh'] = quest:event(12):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Bite_the_Dust.lua"]={["Path"]="scripts/quests/bastok/Bite_the_Dust.lua",["SHA256"]="5ef6c0f9886e8779bd3d63aba4d3b348e4a3c0aaea809f834dda1d8f99729f04",["Text"]="-----------------------------------\n-- Bite the Dust\n-----------------------------------\n-- Log ID: 1, Quest ID: 46\n-- Yazan : !pos -20.06 -3.3 24.471 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BITE_THE_DUST)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 350,\n    title    = xi.title.SAND_BLASTER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Yazan'] = quest:progressEvent(191),\n\n            onEventFinish =\n            {\n                [191] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Yazan'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.SAND_BAT_FANG, 1 } }) then\n                        return quest:progressEvent(193)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questStatus = player:getQuestStatus(quest.areaId, quest.questId)\n\n                    if questStatus == xi.questStatus.QUEST_ACCEPTED then\n                        return quest:event(192)\n                    else\n                        return quest:event(194):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [193] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Blade_of_Darkness.lua"]={["Path"]="scripts/quests/bastok/Blade_of_Darkness.lua",["SHA256"]="3998fda4ad04b50c5bf983cee8664fc3fb484c467f2fbdbe4630ff41cc479ecb",["Text"]="-----------------------------------\n-- Blade of Darkness\n-----------------------------------\n-- Log ID: 1, Quest ID: 28\n-- Gumbah : !pos 52 0 -36 234\n-- TODO: This quest needs verification!\n-----------------------------------\nlocal beadeauxID = zones[xi.zone.BEADEAUX]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_DARKNESS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    keyItem  = xi.keyItem.JOB_GESTURE_DARK_KNIGHT,\n    title    = xi.title.DARK_SIDER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Gumbah'] = quest:progressEvent(99),\n\n            onEventFinish =\n            {\n                [99] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ZERUHN_MINES] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.PALBOROUGH_MINES then\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return 130\n                    elseif not player:hasItem(xi.item.CHAOSBRINGER) then\n                        return 131\n                    end\n                end\n            end,\n\n            onEventFinish =\n            {\n                [130] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CHAOSBRINGER) then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [131] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.CHAOSBRINGER)\n                end,\n            },\n        },\n\n        [xi.zone.BEADEAUX] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.PASHHOW_MARSHLANDS and\n                    player:getCharVar('ChaosbringerKills') >= 100\n                then\n                    return 121\n                end\n            end,\n\n            onEventFinish =\n            {\n                [121] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:unlockJob(xi.job.DRK)\n                        player:messageSpecial(beadeauxID.text.YOU_CAN_NOW_BECOME_A_DARK_KNIGHT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Blade_of_Death.lua"]={["Path"]="scripts/quests/bastok/Blade_of_Death.lua",["SHA256"]="210552f52896ffe5fe1a75afe27f028ed9e76581055144f58e34fe012c36f7bc",["Text"]="-----------------------------------\n-- Blade of Death\n-----------------------------------\n-- Log ID: 1, Quest ID: 47\n-- Gumbah : !pos 52 0 -36 234\n-- qm2    : !pos 206 -60 -101 196\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_DEATH)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.DEATHBRINGER,\n    title    = xi.title.BLACK_DEATH,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_DARKNESS) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Gumbah'] = quest:progressEvent(130),\n\n            onEventFinish =\n            {\n                [130] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_ZEID)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ZERUHN_MINES] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.PALBOROUGH_MINES and\n                    not player:hasItem(xi.item.CHAOSBRINGER)\n                then\n                    return 131\n                end\n            end,\n\n            onEventFinish =\n            {\n                [131] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.CHAOSBRINGER)\n                end,\n            },\n        },\n\n        [xi.zone.GUSGEN_MINES] =\n        {\n            ['qm2'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        player:getCharVar('ChaosbringerKills') >= 200 and\n                        npcUtil.tradeMatches(trade, { { xi.item.CHAOSBRINGER, 1 } })\n                    then\n                        return quest:progressEvent(10)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:delKeyItem(xi.keyItem.LETTER_FROM_ZEID)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Breaking_Stones.lua"]={["Path"]="scripts/quests/bastok/Breaking_Stones.lua",["SHA256"]="c06ce7979a1bc5e6d98263351728897af6948e04c0910855ec36ff6b957e385b",["Text"]="-----------------------------------\n-- Breaking Stones\n-----------------------------------\n-- Log ID: 1, Quest ID: 10\n-- Horatius : !pos -158 -6 -117 235\n-- qm2      : !pos -120.041 2.621 415.989 191\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BREAKING_STONES)\n\nquest.reward =\n{\n    gil      = 400,\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Horatius'] = quest:progressEvent(100),\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Horatius'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.DANGRUF_STONE, 1 } }) then\n                        return quest:progressEvent(101)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Brygid_the_Stylist.lua"]={["Path"]="scripts/quests/bastok/Brygid_the_Stylist.lua",["SHA256"]="f954f817778ce0c8023f8598a325301508209811bc475d89d6be604c0cfd0af6",["Text"]="-----------------------------------\n-- Brygid the Stylist\n-----------------------------------\n-- Log ID: 1, Quest ID: 44\n-- Brygid : !pos -90 -4 -108 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BRYGID_THE_STYLIST)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.GLOVES,\n    title    = xi.title.BRYGID_APPROVED,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Brygid'] = quest:progressEvent(310),\n\n            onEventFinish =\n            {\n                [310] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Brygid'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getEquipID(xi.slot.BODY) == xi.item.ROBE and\n                        player:getEquipID(xi.slot.LEGS) == xi.item.BRONZE_SUBLIGAR\n                    then\n                        return quest:progressEvent(311)\n                    else\n                        return quest:event(310)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [311] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Brygid_the_Stylist_Returns.lua"]={["Path"]="scripts/quests/bastok/Brygid_the_Stylist_Returns.lua",["SHA256"]="31ec382198e963d0a8b9ba77222cff00f029af3666e0d423cff535b07bbd9570",["Text"]="-----------------------------------\n-- Brygid the Stylist Returns\n-----------------------------------\n-- Log ID: 1, Quest ID: 74\n-- Brygid : !pos -90 -4 -108 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BRYGID_THE_STYLIST_RETURNS)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    title    = xi.title.BASTOKS_SECOND_BEST_DRESSED,\n}\n\nlocal requestedBodyItems =\n{\n    xi.item.BREASTPLATE,\n    xi.item.SILVER_MAIL,\n    xi.item.BANDED_MAIL,\n    xi.item.CUIR_BOUILLI,\n    xi.item.RAPTOR_JERKIN,\n    xi.item.PADDED_ARMOR,\n    xi.item.GAMBISON,\n    xi.item.WOOL_GAMBISON,\n    xi.item.VELVET_ROBE,\n    xi.item.SILK_COAT,\n    xi.item.CLOAK,\n    xi.item.WHITE_CLOAK,\n    xi.item.BEAK_JERKIN,\n    xi.item.CARAPACE_HARNESS,\n    xi.item.PYRO_ROBE,\n    xi.item.FROST_ROBE,\n    xi.item.LINEN_DOUBLET,\n    xi.item.WOOL_DOUBLET,\n    xi.item.IRON_SCALE_MAIL,\n    xi.item.BISHOPS_ROBE,\n}\n\nlocal requestedLegItems =\n{\n    xi.item.CUISSES,\n    xi.item.SILVER_HOSE,\n    xi.item.BREECHES,\n    xi.item.CUIR_TROUSERS,\n    xi.item.RAPTOR_TROUSERS,\n    xi.item.BEAK_TROUSERS,\n    xi.item.IRON_SUBLIGAR,\n    xi.item.CARAPACE_SUBLIGAR,\n    xi.item.SCORPION_SUBLIGAR,\n    xi.item.HOSE,\n    xi.item.WOOL_HOSE,\n    xi.item.VELVET_SLOPS,\n    xi.item.SILK_SLOPS,\n    xi.item.LINEN_SLACKS,\n    xi.item.WHITE_SLACKS,\n    xi.item.IRON_CUISSES,\n}\n\n-- [option] = { rewardItem, requiredItem }\nlocal optionToItems =\n{\n    [ 1] = { xi.item.DUENDE_COTEHARDIE,   xi.item.ARIES_SUBLIGAR       },\n    [ 2] = { xi.item.NOKIZARU_GI,         xi.item.TAURUS_SUBLIGAR      },\n    [ 3] = { xi.item.RAPPAREE_HARNESS,    xi.item.GEMINI_SUBLIGAR      },\n    [ 4] = { xi.item.SHINIMUSHA_HARA_ATE, xi.item.CANCER_SUBLIGAR      },\n    [ 5] = { xi.item.WYVERN_MAIL,         xi.item.LEO_SUBLIGAR         },\n    [ 6] = { xi.item.SHIKAREE_AKETON,     xi.item.VIRGO_SUBLIGAR       },\n    [ 7] = { xi.item.CERISE_DOUBLET,      xi.item.LIBRA_SUBLIGAR       },\n    [ 8] = { xi.item.GLAMOR_JUPON,        xi.item.SCORPIUS_SUBLIGAR    },\n    [ 9] = { xi.item.GLOOM_BREASTPLATE,   xi.item.SAGITTARIUS_SUBLIGAR },\n    [10] = { xi.item.NIMBUS_DOUBLET,      xi.item.CAPRICORNUS_SUBLIGAR },\n    [11] = { xi.item.AIKIDO_GI,           xi.item.AQUARIUS_SUBLIGAR    },\n    [12] = { xi.item.PARADE_CUIRASS,      xi.item.PISCES_SUBLIGAR      },\n    [13] = { xi.item.GAUDY_HARNESS,       xi.item.OPHIUCHUS_SUBLIGAR   },\n}\n\nlocal getRandomEquippableItem = function(player, itemList)\n    -- To not repeatedly select a random number and compare, first generate a list\n    -- of known items that can be equipped.\n    local equippableItems = {}\n\n    for _, itemId in ipairs(itemList) do\n        if player:canEquipItem(itemId, false) then\n            table.insert(equippableItems, itemId)\n        end\n    end\n\n    return equippableItems[math.randomInt(1, #equippableItems)]\nend\n\nlocal hasArtifactArmorEquipped = function(player)\n    for equipSlot = xi.slot.HEAD, xi.slot.FEET do\n        if xi.equip.isArtifactArmor(player:getEquipID(equipSlot)) then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_ACCEPTED and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.BRYGID_THE_STYLIST) and\n                hasArtifactArmorEquipped(player)\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Brygid'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasRobeEquipped = player:getEquipID(xi.slot.BODY) == xi.item.ROBE and 1 or 0\n                    local requestedBody   = getRandomEquippableItem(player, requestedBodyItems)\n                    local requestedLegs   = getRandomEquippableItem(player, requestedLegItems)\n\n                    quest:setVar(player, 'requestedBody', requestedBody)\n                    quest:setVar(player, 'requestedLegs', requestedLegs)\n\n                    return quest:progressEvent(380, hasRobeEquipped, requestedBody, requestedLegs, player:getMainJob())\n                end,\n            },\n\n            onEventFinish =\n            {\n                [380] = function(player, csid, option, npc)\n                    player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.BRYGID_THE_STYLIST_RETURNS)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Brygid'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { optionToItems[quest:getVar(player, 'Option')][2], 1 } }) then\n                        return quest:progressEvent(383)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if questOption == 0 then\n                        if\n                            player:getEquipID(xi.slot.BODY) == quest:getVar(player, 'requestedBody') and\n                            player:getEquipID(xi.slot.LEGS) == quest:getVar(player, 'requestedLegs')\n                        then\n                            return quest:progressEvent(382)\n                        else\n                            local hasRobeEquipped = player:getEquipID(xi.slot.BODY) == xi.item.ROBE and 1 or 0\n                            local requestedBody   = quest:getVar(player, 'requestedBody')\n                            local requestedLegs   = quest:getVar(player, 'requestedLegs')\n\n                            return quest:event(381, hasRobeEquipped, requestedBody, requestedLegs, player:getMainJob())\n                        end\n                    else\n                        local optionList = optionToItems[questOption]\n\n                        return quest:event(385, 0, optionList[1], optionList[2])\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [382] = function(player, csid, option, npc)\n                    local rewardItem     = xi.item.DUENDE_COTEHARDIE - 1 + option\n                    local canEquipReward = player:canEquipItem(rewardItem, true) and 1 or 0\n                    local hasReward      = not player:hasItem(rewardItem) and 1 or 0\n\n                    player:updateEvent(0, option - 1, hasReward, canEquipReward)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [382] = function(player, csid, option, npc)\n                    -- Limit the response value to the valid range to prevent client lock-up when this value is re-processed\n                    if optionToItems[option] then\n                        quest:setVar(player, 'Option', option)\n                    end\n                end,\n\n                [383] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, optionToItems[quest:getVar(player, 'Option')][1]) then\n                        player:tradeComplete()\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Buckets_of_Gold.lua"]={["Path"]="scripts/quests/bastok/Buckets_of_Gold.lua",["SHA256"]="35bb01013a2c88cb027524d5ced4eb6a62c180ff2cdb7f9c28265bdceb209667",["Text"]="-----------------------------------\n-- Buckets of Gold\n-----------------------------------\n-- Log ID: 1, Quest ID: 41\n-- Foss : !pos -283 -12 -37 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BUCKETS_OF_GOLD)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 300,\n    title    = xi.title.BUCKET_FISHER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Foss'] = quest:progressEvent(271),\n\n            onEventFinish =\n            {\n                [271] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Foss'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.RUSTY_BUCKET, 5 } }) then\n                        return quest:progressEvent(272)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [272] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Chips.lua"]={["Path"]="scripts/quests/bastok/Chips.lua",["SHA256"]="5044d6d1d88defbc82cebea97824b4c9589c4ee5cea93f33568fe19e67ec3d76",["Text"]="-----------------------------------\n-- Chips\n-----------------------------------\n-- Log ID: 1, Quest ID: 82\n-----------------------------------\n-- CoP 6-4        : !addmission 6 638\n-- CoP 7-1        : !addmission 6 648\n-- Ghebi Damomohe : !pos 15.535 -0.111 -7.603\n-- Cid            : !pos -12 -12 1 237\n-----------------------------------\nlocal metalID = zones[xi.zone.METALWORKS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.CHIPS)\n\nquest.reward =\n{\n    item = xi.item.CCB_POLYMER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Ghebi_Damomohe'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        (player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.ONE_TO_BE_FEARED) or\n                        (player:getCurrentMission(xi.mission.log_id.COP) == xi.mission.id.cop.ONE_TO_BE_FEARED and\n                        xi.mission.getVar(player, xi.mission.log_id.COP, xi.mission.id.cop.ONE_TO_BE_FEARED, 'Status') >= 1))\n                    then\n                        return quest:progressEvent(169)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [169] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    elseif option == 1 then\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CARMINE_CHIP, 1 }, { xi.item.CYAN_CHIP, 1 }, { xi.item.GRAY_CHIP, 1 } }) then\n                        if\n                            player:getFreeSlotsCount() == 0 or\n                            player:hasItem(xi.item.CCB_POLYMER)\n                        then\n                            return player:messageSpecial(metalID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.CCB_POLYMER)\n                        else\n                            return quest:progressEvent(883)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [883] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:addFame(xi.fameArea.SANDORIA, 5)\n                        player:addFame(xi.fameArea.BASTOK, 5)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CARMINE_CHIP, 1 }, { xi.item.CYAN_CHIP, 1 }, { xi.item.GRAY_CHIP, 1 } }) then\n                        if\n                            player:getFreeSlotsCount() == 0 or\n                            player:hasItem(xi.item.CCB_POLYMER)\n                        then\n                            return player:messageSpecial(metalID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.CCB_POLYMER)\n                        else\n                            return quest:progressEvent(884)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [884] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:addFame(xi.fameArea.SANDORIA, 5)\n                        player:addFame(xi.fameArea.BASTOK, 5)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Cids_Secret.lua"]={["Path"]="scripts/quests/bastok/Cids_Secret.lua",["SHA256"]="2a90378e693d87aa50fb14841788c1c17ae2d3b3bf79963a32f8a4d6d934d238",["Text"]="-----------------------------------\n-- Cid's Secret\n-----------------------------------\n-- Log ID: 1, Quest ID: 26\n-- Cid   : !pos -12 -12 1 237\n-- Hilda : !pos -163 -8 13 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.CIDS_SECRET)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.RAM_MANTLE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 4\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] = quest:progressEvent(507),\n\n            onEventFinish =\n            {\n                [507] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.UNFINISHED_LETTER) then\n                        return quest:progressEvent(509)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(508):importantEvent()\n                    else\n                        return quest:event(502):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [509] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.UNFINISHED_LETTER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Hilda'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.ROLANBERRY_874_CE, 1 } })\n                    then\n                        return quest:progressEvent(133)\n                    end\n                end,\n\n                onTrigger = quest:progressEvent(132),\n            },\n\n            onEventFinish =\n            {\n                [132] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [133] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.UNFINISHED_LETTER)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Hilda'] = quest:event(49):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/DRK_AF1_Dark_Legacy.lua"]={["Path"]="scripts/quests/bastok/DRK_AF1_Dark_Legacy.lua",["SHA256"]="57538cea98cf0aa4832efd453435e5875cece2ef0950c90b564c01edf8bbc706",["Text"]="-----------------------------------\n-- Dark Legacy\n-----------------------------------\n-- Log ID: 1, Quest ID: 57\n-- Raibaht        : !pos -27 -10 -1 237\n-- Mighty Fist    : !pos -47 2 -30 237\n-- Cochal-Monchal : !pos -52 -6 110 238\n-- Quu Bokye      : !pos -159 16 181 145\n-- qm1            : !pos -58 0 -449 145\n-----------------------------------\nlocal giddeusID = zones[xi.zone.GIDDEUS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.DARK_LEGACY)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.RAVEN_SCYTHE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.DRK and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Raibaht'] = quest:progressEvent(751),\n\n            onEventFinish =\n            {\n                [751] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Mighty_Fist'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(752)\n                    elseif player:hasKeyItem(xi.keyItem.DARKSTEEL_FORMULA) then\n                        return quest:event(754)\n                    end\n                end,\n            },\n\n            ['Raibaht'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.DARKSTEEL_FORMULA) then\n                        return quest:progressEvent(755)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [752] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_THE_DARKSTEEL_FORGE)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [755] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.DARKSTEEL_FORMULA)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Cochal-Monchal'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(697)\n                    elseif questProgress == 2 then\n                        return quest:event(698)\n                    elseif player:hasKeyItem(xi.keyItem.DARKSTEEL_FORMULA) then\n                        return quest:event(699)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [697] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.LETTER_FROM_THE_DARKSTEEL_FORGE)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.GIDDEUS] =\n        {\n            ['qm1'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        not GetMobByID(giddeusID.mob.VAA_HUJA_THE_ERUDITE):isSpawned() and\n                        npcUtil.tradeMatches(trade, { { xi.item.YAGUDO_CHERRY, 1 } })\n                    then\n                        player:tradeComplete()\n                        SpawnMob(giddeusID.mob.VAA_HUJA_THE_ERUDITE):updateClaim(player)\n\n                        return quest:messageSpecial(giddeusID.text.SENSE_OF_FOREBODING)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.DARKSTEEL_FORMULA) and\n                        quest:getVar(player, 'Prog') == 3\n                    then\n                        return quest:keyItem(xi.keyItem.DARKSTEEL_FORMULA)\n                    end\n                end,\n            },\n\n            ['Quu_Bokye'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        quest:getVar(player, 'Option') == 0 and\n                        npcUtil.tradeMatches(trade, { { xi.item.YAGUDO_CHERRY, 1 } })\n                    then\n                        return quest:progressEvent(62)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:event(61)\n                    end\n                end,\n            },\n\n            ['Vaa_Huja_the_Erudite'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [62] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/DRK_AF2_Dark_Puppet.lua"]={["Path"]="scripts/quests/bastok/DRK_AF2_Dark_Puppet.lua",["SHA256"]="bb36fb243495fb0504a3524e058edbb687657ee584c69c5577dc7677a8ffd806",["Text"]="-----------------------------------\n-- Dark Puppet\n-----------------------------------\n-- Log ID: 1, Quest ID: 58\n-- Cid         : !pos -12 -12 1 237\n-- qm4 (Axe)   : !pos -52 27 -85 193\n-- qm5 (Sword) : !pos -92 -28 -70 193\n-- qm6 (Soul)  : !pos -132 -27 -245 193\n-----------------------------------\nlocal ordellesID = zones[xi.zone.ORDELLES_CAVES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.DARK_PUPPET)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.CHAOS_SOLLERETS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.DARK_LEGACY) and\n                player:getMainJob() == xi.job.DRK and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] = quest:progressEvent(760),\n\n            onEventFinish =\n            {\n                [760] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ORDELLES_CAVES] =\n        {\n            ['qm4'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasItem(xi.item.GERWITZS_AXE) and\n                        npcUtil.tradeMatches(trade, { { xi.item.DARKSTEEL_INGOT, 1 } }) and\n                        npcUtil.popFromQM(player, npc, ordellesID.mob.DARK_PUPPET_OFFSET, { hide = 0 })\n                    then\n                        player:tradeComplete()\n\n                        return quest:messageSpecial(ordellesID.text.SENSE_A_FOUL_PRESENCE)\n                    end\n                end,\n            },\n\n            ['qm5'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasItem(xi.item.GERWITZS_SWORD) and\n                        npcUtil.tradeMatches(trade, { { xi.item.GERWITZS_AXE, 1 } }) and\n                        npcUtil.popFromQM(player, npc, ordellesID.mob.DARK_PUPPET_OFFSET + 1, { hide = 0 })\n                    then\n                        player:tradeComplete()\n\n                        return quest:messageSpecial(ordellesID.text.SENSE_A_FOUL_PRESENCE)\n                    end\n                end,\n            },\n\n            ['qm6'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeMatches(trade, { { xi.item.GERWITZS_SWORD, 1 } }) and\n                        npcUtil.popFromQM(player, npc, ordellesID.mob.DARK_PUPPET_OFFSET + 2, { hide = 0 })\n                    then\n                        player:tradeComplete()\n\n                        return quest:messageSpecial(ordellesID.text.SENSE_A_FOUL_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Gerwitzs_Soul'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 0 then\n                    return 10\n                end\n            end,\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 2 then\n                    return 122\n                end\n            end,\n\n            onEventFinish =\n            {\n                [122] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/DRK_AF3_Blade_of_Evil.lua"]={["Path"]="scripts/quests/bastok/DRK_AF3_Blade_of_Evil.lua",["SHA256"]="33d7d5c551be8a2d740d2ee8c08e96c5c15dc54ede2f56d05e2a6af470d6c65a",["Text"]="-----------------------------------\n-- Blade of Evil\n-----------------------------------\n-- Log ID: 1, Quest ID: 59\n-- qm1 : !pos 84 -79 77 157\n-----------------------------------\nlocal middleDelkfuttsID = zones[xi.zone.MIDDLE_DELKFUTTS_TOWER]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_EVIL)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.CHAOS_BURGEONET,\n    title    = xi.title.PARAGON_OF_DARK_KNIGHT_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.DARK_PUPPET) and\n                player:getMainJob() == xi.job.DRK and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.BEADEAUX] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.PASHHOW_MARSHLANDS then\n                    return 122\n                end\n            end,\n\n            onEventFinish =\n            {\n                [122] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MIDDLE_DELKFUTTS_TOWER] =\n        {\n            ['qm1'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        not GetMobByID(middleDelkfuttsID.mob.BLADE_OF_EVIL_OFFSET + 0):isSpawned() and\n                        not GetMobByID(middleDelkfuttsID.mob.BLADE_OF_EVIL_OFFSET + 1):isSpawned() and\n                        not GetMobByID(middleDelkfuttsID.mob.BLADE_OF_EVIL_OFFSET + 2):isSpawned() and\n                        npcUtil.tradeMatches(trade, { { xi.item.VIAL_OF_QUADAV_MAGE_BLOOD, 1 } })\n                    then\n                        player:tradeComplete()\n                        SpawnMob(middleDelkfuttsID.mob.BLADE_OF_EVIL_OFFSET + 0):updateClaim(player)\n                        SpawnMob(middleDelkfuttsID.mob.BLADE_OF_EVIL_OFFSET + 1):updateEnmity(player)\n                        SpawnMob(middleDelkfuttsID.mob.BLADE_OF_EVIL_OFFSET + 2):updateEnmity(player)\n\n                        return quest:messageSpecial(middleDelkfuttsID.text.SENSE_A_FOUL_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Gerwitzs_Scythe'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [8] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(14)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Drachenfall.lua"]={["Path"]="scripts/quests/bastok/Drachenfall.lua",["SHA256"]="62e0c6441c2a5327fe1ab2e5ad65e493fccc1ba1c0046ae642ab7c3c78b9ed3b",["Text"]="-----------------------------------\n-- Drachenfall\n-----------------------------------\n-- Log ID: 1, Quest ID: 31\n-- Black Mud      : !pos 63.514 7 -0.972 234\n-- Waterfall Base : !pos -217.594 98.644 464.722 106\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.DRACHENFALL)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.BASTOK,\n    gil = 2000,\n    title = xi.title.DRACHENFALL_ASCETIC,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Black_Mud'] =\n            {\n                onTrigger = quest:progressEvent(101)\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.BRASS_CANTEEN) then\n                        quest:begin(player)\n                    end\n                end,\n            }\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Black_Mud'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CANTEEN_OF_DRACHENFALL_WATER, 1 } }) then\n                        return quest:progressEvent(103)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        not player:findItem(xi.item.BRASS_CANTEEN) and\n                        not player:findItem(xi.item.CANTEEN_OF_DRACHENFALL_WATER)\n                    then\n                        return quest:progressEvent(102)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [102] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.BRASS_CANTEEN)\n                end,\n\n                [103] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Waterfall_Base'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeMatches(trade, { { xi.item.BRASS_CANTEEN, 1 } }) and\n                        npcUtil.giveItem(player, xi.item.CANTEEN_OF_DRACHENFALL_WATER)\n                    then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Eco_Warrior.lua"]={["Path"]="scripts/quests/bastok/Eco_Warrior.lua",["SHA256"]="2401632012ee69ce0a9fc6a4afee7a9bd8fbff8523f34ff5f057d783cd5a3749",["Text"]="-----------------------------------\n-- Eco-Warrior (Bastok)\n-----------------------------------\n-- Log ID: 1, Quest ID: 65\n-- !addquest 1 65\n-- Raifa : !pos -166.416 -8.48 7.153 236\n-- Degga : !pos 40 -68 -259 196\n-- qm5   : !pos 22.796 -61.156 -19.687 196\n-----------------------------------\n-- The indigested ore alone gates the turn-in. Returning to Degga first is optional.\n-- Event 16 does not remove the level restriction. Removal stays available through event 15.\n-- Completing any nation's Eco-Warrior locks all three until the next conquest tally.\n-----------------------------------\nlocal gusgenID = zones[xi.zone.GUSGEN_MINES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.ECO_WARRIOR)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 5000,\n    item     = xi.item.DRAGON_CHRONICLES,\n    title    = xi.title.CERULEAN_SOLDIER,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Raifa'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(283) -- Already on another nation's Eco-Warrior.\n                    elseif\n                        player:getFameLevel(xi.fameArea.BASTOK) >= 1 and\n                        player:getCharVar('EcoReset') == 0\n                    then\n                        return quest:progressEvent(278) -- Offers the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [278] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GUSGEN_MINES] =\n        {\n            ['Degga'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.INDIGESTED_ORE) and\n                        quest:getVar(player, 'Informed') == 0\n                    then\n                        return quest:progressEvent(16) -- Sends the player to Raifa.\n                    elseif player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) then\n                        return quest:progressEvent(15) -- Offers to remove the ointment.\n                    elseif not player:hasKeyItem(xi.keyItem.INDIGESTED_ORE) then\n                        return quest:progressEvent(13) -- Offers to apply the ointment.\n                    end\n                end,\n            },\n\n            ['Pudding'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if not player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) then\n                        return\n                    end\n\n                    for i = gusgenID.mob.PUDDING_OFFSET, gusgenID.mob.PUDDING_OFFSET + 1 do\n                        local nmCheck = GetMobByID(i)\n\n                        if\n                            i ~= mob:getID() and\n                            nmCheck and\n                            nmCheck:isAlive()\n                        then\n                            return\n                        end\n                    end\n\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        player:hasStatusEffect(xi.effect.LEVEL_RESTRICTION) and\n                        npcUtil.popFromQM(player, npc, { gusgenID.mob.PUDDING_OFFSET, gusgenID.mob.PUDDING_OFFSET + 1 }, { claim = true, look = true, hide = 0 })\n                    then\n                        return quest:messageSpecial(gusgenID.text.OINTMENT_DRAWS_MONSTERS)\n                    elseif\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.INDIGESTED_ORE)\n                    then\n                        return quest:keyItem(xi.keyItem.INDIGESTED_ORE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [13] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:addStatusEffect(xi.effect.LEVEL_RESTRICTION, {\n                            power    = 25,\n                            subPower = 1, -- exp uses actual level and not the restricted level.\n                            origin   = player,\n                            flag     = xi.effectFlag.ON_ZONE\n                        })\n                    end\n                end,\n\n                [15] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:delStatusEffect(xi.effect.LEVEL_RESTRICTION)\n                    end\n                end,\n\n                [16] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Informed', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Raifa'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.INDIGESTED_ORE) then\n                        return quest:progressEvent(282) -- Completes the quest.\n                    else\n                        return quest:event(280) -- Reminder to see Degga.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [282] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.INDIGESTED_ORE)\n                        player:setCharVar('EcoReset', 1, NextConquestTally())\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Raifa'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Repeatable after the next conquest tally.\n                    if\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.ECO_WARRIOR) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(283) -- Already on another nation's Eco-Warrior.\n                    elseif\n                        player:getFameLevel(xi.fameArea.BASTOK) >= 1 and\n                        player:getCharVar('EcoReset') == 0\n                    then\n                        return quest:progressEvent(278) -- Offers the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [278] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.ECO_WARRIOR)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
